package com.fream.back.domain.notification.portone;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fream.back.domain.notification.dto.paymentInfo.NotificationInfoCreateDto;
import com.fream.back.domain.notification.entity.NotificationInfo;
import com.fream.back.domain.notification.exception.NotificationApiException;
import com.fream.back.domain.notification.exception.NotificationErrorCode;
import com.fream.back.domain.notification.exception.NotificationException;
import com.fream.back.domain.notification.exception.NotificationProcessingException;
import com.fream.back.domain.notification.util.NotificationCardUtils;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;

import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;





@Service
@RequiredArgsConstructor
@Slf4j
public class PortOneApiClient {

    private final RestTemplate restTemplate;

    private static final String BASE_URL = "https://api.iamport.kr";
    private static final String TOKEN_URL = "/users/getToken";
    private static final String ONE_TIME_PAYMENT_URL = "/subscribe/payments/onetime";
    private static final String CANCEL_PAYMENT_URL = "/payments/cancel";

    @Value("${imp.key}")
    private String impKey;

    @Value("${imp.secret}")
    private String impSecret;

    @Value("${imp.pg}")
    private String pg;

    @Value("${imp.storeId}")
    private String storeId;

    @Value("${payment.api.timeout:10000}")
    private int apiTimeout;

    @Value("${payment.retry.max-attempts:3}")
    private int maxRetryAttempts;

    @Value("${payment.retry.delay-ms:1000}")
    private int retryDelayMs;






    @Retryable(
            value = {NotificationApiException.class},
            maxAttempts = 3,
            backoff = @Backoff(delay = 1000)
    )
    public String getAccessToken() {
        Instant start = Instant.now();
        String url = BASE_URL + TOKEN_URL;

        log.info("PortOne API 토큰 발급 요청 시작");


        Map<String, String> requestBody = new HashMap<>();
        requestBody.put("imp_key", impKey);
        requestBody.put("imp_secret", impSecret);


        HttpHeaders headers = new HttpHeaders();
